inline std::string_view poolRuleMessageKeyName(PoolRuleMessageKey key){
    static constexpr std::array<std::string_view,poolRuleMessageKeyCount> names={{"pool.rule.before_both","pool.rule.before_tls","pool.rule.before_tcp","pool.rule.before_unset","pool.rule.after_both","pool.rule.after_tls","pool.rule.after_tcp","pool.rule.after_unset"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage poolRuleMessage(std::string_view language,PoolRuleMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=poolRuleMessageKeyCount)return {};
    const auto &source=poolRuleLocalePacks()[0];const auto *selected=&source;for(const auto &pack:poolRuleLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string poolRuleEnglish(PoolRuleMessageKey key,const MessageArguments &arguments){
    if(arguments.size()>4)return {};
    const auto text=poolRuleMessage("en",key).text;std::vector<std::string_view> expected,supplied;
    if(text.empty()||!templateParameters(text,&expected))return {};
    for(const auto &arg:arguments){if(arg.first.size()>32||arg.second.empty()||arg.second.size()>300||!std::all_of(arg.second.begin(),arg.second.end(),[](unsigned char c){return c>=32&&c<=126;}))return {};supplied.push_back(arg.first);}
    std::sort(supplied.begin(),supplied.end());if(supplied!=expected)return {};
    std::string result;std::size_t at=0;
    while(at<text.size()){const auto start=text.find('{',at);if(start==text.npos){result.append(text.substr(at));break;}result.append(text.substr(at,start-at));const auto end=text.find('}',start);
        const auto name=text.substr(start+1,end-start-1);const auto found=std::find_if(arguments.begin(),arguments.end(),[&](const auto &arg){return arg.first==name;});if(found==arguments.end())return {};
        result+=found->second;if(result.size()>4096)return {};at=end+1;
    }
    return result.size()<=4096?result:std::string{};
}
